script:
/* Attendance Dashboard — client side.
 *
 * Single IIFE so the deployment shape matches Frappe's Custom HTML Block
 * expectations, but organized top-to-bottom by responsibility. Each section
 * is self-contained and labeled. Functions are hoisted via `function` so the
 * reading order does not have to match the call order.
 *
 *   1. STATE           — multi-select state, dirty-flag, debounced init
 *   2. UTILITIES       — escape / hash / format helpers
 *   3. DOM ACCESSORS   — cached root_element queries
 *   4. LOADERS         — inline / table spinners and button busy state
 *   5. MULTI-SELECT    — filter dropdowns (ward, cp-type, org, ...)
 *   6. ACTIVE FILTERS  — chip strip below the filter bar
 *   7. DATA ADAPTER    — server payload → row model + KPIs
 *   8. RENDERING       — KPI tiles, tab counts, table HTML
 *   9. NETWORK         — frappe RPC + client-side field fallback
 *  10. EXPORT          — Excel workbook with status sheets
 *  11. WIRING          — top-level DOM event hooks fired once on load
 *
 * Data flow:
 *   WIRING.init()
 *     → NETWORK.init()          frappe.call get_data_k
 *     → MULTI-SELECT.populate  populate dropdowns
 *     → DATA ADAPTER            buildEmployeeRows()
 *     → RENDERING               renderAll() → KPIs, tabs, table
 */

(function () {
  if (typeof root_element === "undefined") return;

  // ============================================================
  // 1. STATE
  // ============================================================

  const MS_ORDER = [
    "ms-ward",
    "ms-cp-type",
    "ms-org",
    "ms-dept",
    "ms-desig",
    "ms-shift",
  ];

  const FILTER_LABEL_MAP = {
    "ms-ward":    "Ward",
    "ms-cp-type": "Care Provider",
    "ms-org":     "Organization",
    "ms-dept":    "Department",
    "ms-desig":   "Designation",
    "ms-shift":   "Shift",
  };

  const msState = {
    "ms-ward":    { selected: [], all: [], placeholder: "Wards" },
    "ms-cp-type": { selected: [], all: [], placeholder: "Care Provider" },
    "ms-org":     { selected: [], all: [], placeholder: "Organizations" },
    "ms-dept":    { selected: [], all: [], placeholder: "Departments" },
    "ms-desig":   { selected: [], all: [], placeholder: "Designations" },
    "ms-shift":   { selected: [], all: [], placeholder: "Shifts" },
  };

  // `filtersDirty` is set true ONLY when something the server cares about
  // changes. scheduleInit() bails if dirty=false, so re-clicks without state
  // change don't hit the API.
  let initTimer = null;
  let filtersDirty = false;

  let latestRows = [];

  function markDirty() { filtersDirty = true; }

  function scheduleInit(delay = 300) {
    if (!filtersDirty) return;
    clearTimeout(initTimer);
    initTimer = setTimeout(() => {
      if (!filtersDirty) return;
      filtersDirty = false;
      init();
    }, delay);
  }

  function getSelected(id) { return msState[id].selected; }

  // ============================================================
  // 2. UTILITIES
  // ============================================================

  const escapeHtml = (s) =>
    String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  const escapeAttr = (s) => escapeHtml(s).replace(/"/g, "&quot;");

  // Stable hash for unique-id suffix collisions (e.g. "ICU-1" vs "ICU 1").
  function hashStr(s) {
    let h = 0;
    for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0;
    return Math.abs(h);
  }

  // Cached once per buildEmployeeRows call. Constructing these in cell
  // formatters on a 2000-row table is the #1 hot spot.
  function buildFormatters() {
    const timeFmt = new Intl.DateTimeFormat("en-GB", {
      hour: "2-digit", minute: "2-digit", hour12: false,
    });
    const dateFmt = new Intl.DateTimeFormat("en-GB", {
      day: "2-digit", month: "2-digit", year: "numeric",
    });
    const fmtTime = (v) => {
      if (!v) return "—";
      const d = new Date(v);
      return isNaN(d) ? "—" : timeFmt.format(d);
    };
    const fmtDate = (v) => {
      if (!v) return "—";
      const d = new Date(v);
      return isNaN(d) ? "—" : dateFmt.format(d);
    };
    const fmtHours = (v) => {
      if (v === null || v === undefined || v === "") return "—";
      const n = Number(v);
      if (isNaN(n) || n < 0) return "—";
      const hours = Math.floor(n);
      const minutes = Math.round((n - hours) * 60);
      if (minutes === 60) return `${hours + 1}h 0m`;
      return `${hours}h ${minutes}m`;
    };
    return { fmtTime, fmtDate, fmtHours };
  }

  function badgeClass(status) {
    if (status === "Present")  return "badge-green";
    if (status === "Absent")   return "badge-red";
    if (status === "Half Day") return "badge-amber";
    return "badge-gray";
  }

  // ============================================================
  // 3. DOM ACCESSORS
  // ============================================================

  const get = (s) => root_element.querySelector(s);

  const dom = { tbody: null, tabEls: null };

  function tbody()           { return dom.tbody || (dom.tbody = get("#emp-table-body")); }
  function tabEls()          { return dom.tabEls || (dom.tabEls = root_element.querySelectorAll(".status-tab")); }
  function resetDomCache()   { dom.tbody = null; dom.tabEls = null; }

  function closeAllDropdowns() {
    root_element.querySelectorAll(".ms-dropdown.open").forEach((d) => d.classList.remove("open"));
    root_element.querySelectorAll(".ms-trigger.open").forEach((t) => t.classList.remove("open"));
  }

  // ============================================================
  // 4. LOADERS
  // ============================================================

  function showInlineLoader(msg) {
    const statusTabs = root_element.querySelector(".status-tabs");
    if (!statusTabs || statusTabs.querySelector(".inline-loader")) return;
    const loader = document.createElement("div");
    loader.className = "inline-loader";
    loader.innerHTML =
      `<span class="inline-loader-spinner"></span>` +
      `<span class="inline-loader-text">${escapeHtml(msg || "Loading...")}</span>`;
    loader.style.cssText =
      "display:flex;align-items:center;gap:6px;padding:4px 10px;margin-left:auto;" +
      "background:#f5f7fa;border:1px solid #e0e6ed;border-radius:6px;" +
      "color:#4a5568;font-size:11px;width:fit-content;align-self:center;";
    statusTabs.style.display = "flex";
    statusTabs.style.alignItems = "center";
    statusTabs.appendChild(loader);
  }

  function hideInlineLoader() {
    const l = root_element.querySelector(".inline-loader");
    if (l) l.remove();
  }

  function setBtnLoading(btn, loading) {
    if (!btn) return;
    if (loading) {
      if (btn.dataset.busy === "1") return;
      btn.dataset.busy = "1";
      btn.dataset.originalText = btn.innerHTML;
      btn.innerHTML =
        `<span class="btn-spinner"></span> ` +
        escapeHtml(btn.dataset.originalText || btn.textContent || "");
      btn.style.cssText =
        (btn.style.cssText || "") +
        ";opacity:0.7;cursor:wait;pointer-events:none;";
    } else {
      if (btn.dataset.originalText) btn.innerHTML = btn.dataset.originalText;
      btn.style.opacity = "";
      btn.style.pointerEvents = "";
      delete btn.dataset.busy;
      delete btn.dataset.originalText;
    }
  }

  // ============================================================
  // 5. MULTI-SELECT
  // ============================================================

  function buildMultiSelect(id) {
    const wrap = root_element.querySelector("#" + id);
    if (!wrap) return;
    const trigger = wrap.querySelector(".ms-trigger");
    const dropdown = wrap.querySelector(".ms-dropdown");
    const search = wrap.querySelector(".ms-search input");

    // Without stopPropagation, clicking inside the dropdown closes it on
    // the same click (via the document-level closeAllDropdowns listener).
    dropdown.addEventListener("click", (e) => e.stopPropagation());

    trigger.addEventListener("click", (e) => {
      e.stopPropagation();
      const isOpen = dropdown.classList.contains("open");
      closeAllDropdowns();
      if (!isOpen) {
        dropdown.classList.add("open");
        trigger.classList.add("open");
        search.value = "";
        renderOptions(id, "");
        setTimeout(() => search.focus(), 50);
      }
    });

    search.addEventListener("input", () => renderOptions(id, search.value));
    search.addEventListener("click",    (e) => e.stopPropagation());
    search.addEventListener("keydown",  (e) => e.stopPropagation());
    search.addEventListener("keyup",    (e) => e.stopPropagation());
  }

  function renderOptions(id, search) {
    const wrap = root_element.querySelector("#" + id);
    if (!wrap) return;
    const state = msState[id];
    const container = wrap.querySelector(".ms-options");
    const q = (search || "").toLowerCase().trim();
    const filtered = state.all.filter((v) => String(v).toLowerCase().includes(q));

    if (filtered.length === 0) {
      container.innerHTML = `<div class="ms-no-results">No results</div>`;
      return;
    }

    container.innerHTML = filtered
      .map((v) => {
        const checked = state.selected.includes(v) ? "checked" : "";
        const safeId =
          `${id}-opt-${String(v).replace(/[^a-z0-9]/gi, "_")}-${hashStr(String(v))}`;
        return `<div class="ms-option">
                <input type="checkbox" id="${safeId}" value="${escapeAttr(v)}" ${checked}>
                <label for="${safeId}" title="${escapeAttr(v)}">${escapeHtml(v)}</label>
            </div>`;
      })
      .join("");

    container.querySelectorAll("input[type=checkbox]").forEach((cb) => {
      cb.addEventListener("change", () => {
        const val = cb.value;
        const before = state.selected.length;
        if (cb.checked) {
          if (!state.selected.includes(val)) state.selected.push(val);
        } else {
          state.selected = state.selected.filter((s) => s !== val);
        }
        if (state.selected.length !== before) markDirty();
        updateTriggerLabel(id);
        clearDownstream(id);
        // Pass the search input's string value, not the input element.
        renderOptions(id, search.value);
        scheduleInit(200);
      });
    });
  }

  function clearDownstream(changedId) {
    const idx = MS_ORDER.indexOf(changedId);
    MS_ORDER.slice(idx + 1).forEach((downId) => {
      msState[downId].selected = [];
      updateTriggerLabel(downId);
    });
  }

  function updateTriggerLabel(id) {
    const wrap = root_element.querySelector("#" + id);
    if (!wrap) return;
    const trigger = wrap.querySelector(".ms-trigger");
    const state = msState[id];
    if (state.selected.length === 0) {
      trigger.textContent = state.placeholder;
      trigger.setAttribute("title", state.placeholder);
      trigger.classList.remove("has-selection");
    } else if (state.selected.length === 1) {
      trigger.innerHTML =
        `<span class="ms-count-badge">1</span> ${escapeHtml(state.selected[0])}`;
      trigger.setAttribute("title", state.selected[0]);
      trigger.classList.add("has-selection");
    } else {
      trigger.innerHTML =
        `<span class="ms-count-badge">${state.selected.length}</span> ${escapeHtml(state.placeholder)}`;
      trigger.setAttribute("title", `${state.selected.length} selected`);
      trigger.classList.add("has-selection");
    }
    renderActiveFilters();
  }

  function populateMultiSelect(id, list) {
    const state = msState[id];
    const newAll = [...new Set(list)].filter(Boolean).sort();
    const wrap = root_element.querySelector("#" + id);
    const dropdown = wrap?.querySelector(".ms-dropdown");
    const isOpen = dropdown?.classList.contains("open");

    // Merge new options into existing list — both when the dropdown is open
    // AND when closed, so previously selected values don't vanish.
    const merged = new Set([...state.all, ...newAll, ...state.selected]);
    state.all = [...merged].sort();

    state.selected = state.selected.filter((s) => state.all.includes(s));
    updateTriggerLabel(id);

    if (isOpen) {
      const search = wrap.querySelector(".ms-search input");
      renderOptions(id, search.value);
    }
  }

  // ============================================================
  // 6. ACTIVE FILTERS chip strip
  // ============================================================

  function todayLocalISO() {
    const t = new Date();
    return new Date(t.getTime() - t.getTimezoneOffset() * 60000)
      .toISOString()
      .split("T")[0];
  }

  function renderActiveFilters() {
    const strip = root_element.querySelector("#active-filters");
    if (!strip) return;

    const chips = [];
    for (const id of MS_ORDER) {
      const sel = msState[id].selected;
      if (!sel || !sel.length) continue;
      const label = FILTER_LABEL_MAP[id] || id;
      for (const v of sel) chips.push({ filterId: id, label, value: v });
    }

    const dateEl = root_element.querySelector("#single-date");
    if (dateEl && dateEl.value && dateEl.value !== todayLocalISO()) {
      chips.push({ filterId: "__date__", label: "Date", value: dateEl.value });
    }

    if (chips.length === 0) {
      strip.hidden = true;
      strip.innerHTML = "";
      return;
    }

    const parts = [
      `<span class="active-filters-label">${chips.length} filter${chips.length === 1 ? "" : "s"} applied</span>`,
    ];
    for (const c of chips) {
      parts.push(
        `<span class="active-filter-chip" data-filter-id="${escapeAttr(c.filterId)}" data-value="${escapeAttr(c.value)}">` +
          `${escapeHtml(c.label)}: <b>${escapeHtml(c.value)}</b>` +
          `<span class="chip-x" title="Remove this filter">×</span>` +
          `</span>`,
      );
    }
    parts.push(
      `<button type="button" class="active-filters-clear">Clear all</button>`,
    );
    strip.hidden = false;
    strip.innerHTML = parts.join("");

    strip.querySelectorAll(".active-filter-chip").forEach((chip) => {
      const fid = chip.getAttribute("data-filter-id");
      const val = chip.getAttribute("data-value");
      chip.querySelector(".chip-x")?.addEventListener("click", (e) => {
        e.stopPropagation();
        if (fid === "__date__") {
          const dEl = root_element.querySelector("#single-date");
          if (dEl) dEl.value = todayLocalISO();
        } else {
          const st = msState[fid];
          st.selected = st.selected.filter((s) => s !== val);
          updateTriggerLabel(fid);
        }
        markDirty();
        scheduleInit(0);
      });
    });
    strip.querySelector(".active-filters-clear")?.addEventListener("click", () => {
      MS_ORDER.forEach((id) => { msState[id].selected = []; updateTriggerLabel(id); });
      resetDateInputs();
      markDirty();
      scheduleInit(0);
    });
  }

  function resetDateInputs() {
    const dEl = get("#single-date");
    if (dEl) dEl.value = todayLocalISO();
  }

  // ============================================================
  // 7. DATA ADAPTER
  //   server payload → { rows, result } where result has strict per-status
  //   KPI counts. No heuristic, no derivation — Attendance is the source.
  // ============================================================

  function buildEmployeeRows(data) {
    const empDeptMap        = (data && typeof data.emp_dept_map === "object")        ? data.emp_dept_map        : {};
    const empNameMap        = (data && typeof data.emp_name_map === "object")        ? data.emp_name_map        : {};
    const empDesignationMap = (data && typeof data.emp_designation_map === "object") ? data.emp_designation_map : {};
    const empDefaultShiftMap = data.emp_default_shift_map || {};
    const empWardMap        = (data && typeof data.emp_ward_map === "object")        ? data.emp_ward_map        : {};
    const empOrgMap         = (data && typeof data.emp_org_map === "object")         ? data.emp_org_map         : {};
    const attendanceByEmp   = (data && typeof data.attendance_by_emp === "object")  ? data.attendance_by_emp   : {};

    const rawAllEmployee = data && data.all_employee;
    let allEmployee;
    if (Object.keys(empDeptMap).length)            allEmployee = Object.keys(empDeptMap);
    else if (Array.isArray(rawAllEmployee))        allEmployee = rawAllEmployee;
    else if (rawAllEmployee && typeof rawAllEmployee === "object") allEmployee = Object.keys(rawAllEmployee);
    else                                           allEmployee = [];

    const employeeLogs = {};
    (data.all_checkin || []).forEach((log) => {
      const eid = log.employee;
      if (!eid) return;
      const bucket = employeeLogs[eid] || (employeeLogs[eid] = { firstIn: null, lastOut: null });
      const t = log.time;
      if (!t) return;
      if      (log.log_type === "IN")  { if (!bucket.firstIn || t < bucket.firstIn.time) bucket.firstIn = log; }
      else if (log.log_type === "OUT") { if (!bucket.lastOut  || t > bucket.lastOut.time)  bucket.lastOut  = log; }
    });

    // === Status: Attendance doctype is the single source of truth. ===
    const statusByEmp = {};
    for (let i = 0; i < allEmployee.length; i++) {
      const empId = allEmployee[i];
      const attRow = attendanceByEmp[empId];
      statusByEmp[empId] =
        attRow && Object.keys(attRow).length ? (attRow.status || "Absent") : "Absent";
    }

    // Per-status counts.
    //   present_count     = rows with status "Present" or "Half Day" (rolls up)
    //   present_only_count= rows with status "Present" only
    //   half_day_count    = rows with status "Half Day" (separate breakdown)
    //   absent_count      = rows with status "Absent"
    let presentCount = 0,
      presentOnlyCount = 0,
      halfDayCount = 0,
      absentCount = 0;
    for (const empId in statusByEmp) {
      const s = statusByEmp[empId];
      if (s === "Present") {
        presentCount++;
        presentOnlyCount++;
      } else if (s === "Half Day") {
        // Half Day rolls into the Present KPI (e.g. 15 Present + 7 Half Day
        // = 22). The dedicated Half Day tab/counter still tracks them
        // separately so the breakdown isn't lost.
        presentCount++;
        halfDayCount++;
      } else if (s === "Absent") {
        absentCount++;
      }
    }

    const { fmtTime, fmtDate, fmtHours } = buildFormatters();

    const rows = new Array(allEmployee.length);
    for (let i = 0; i < allEmployee.length; i++) {
      const empId = allEmployee[i];
      const firstIn = employeeLogs[empId]?.firstIn || null;
      const att = attendanceByEmp[empId];
      const attDate         = att ? (att.attendance_date || null) : null;
      const inTimeRaw       = att ? (att.first_in || att.in_time || null) : null;
      const outTimeRaw      = att ? (att.last_out || att.out_time || null) : null;
      const workingHoursRaw = att ? (att.working_hours ?? null) : null;

      rows[i] = {
        id: empId,
        name:           (firstIn && firstIn.employee_name) || empNameMap[empId]        || empId,
        department:     empDeptMap[empId]                                              || "—",
        shift:          empDefaultShiftMap[empId]                                      || (firstIn && firstIn.shift)        || "—",
        designation:    empDesignationMap[empId]                                       || (firstIn && firstIn.designation)  || "—",
        ward:           empWardMap[empId]                                               || (firstIn && firstIn.custom_ward)  || "—",
        organization:   empOrgMap[empId]                                                || (firstIn && firstIn.company)      || "—",
        attendance_date:       fmtDate(attDate),
        attendance_date_raw:   attDate,
        in_time:              fmtTime(inTimeRaw),
        in_time_raw:          inTimeRaw,
        out_time:             fmtTime(outTimeRaw),
        out_time_raw:         outTimeRaw,
        working_hours:        fmtHours(workingHoursRaw),
        working_hours_raw:    workingHoursRaw,
        status: statusByEmp[empId] || "Absent",
      };
    }

    rows.sort((a, b) => String(a.name).localeCompare(String(b.name)));

    return {
      rows,
      result: {
        present_count:           presentCount,
        present_only_count:      presentOnlyCount,
        half_day_count:          halfDayCount,
        absent_count:            absentCount,
        total_emp_count:         allEmployee.length,
      },
    };
  }

  // ============================================================
  // 8. RENDERING
  // ============================================================

  function renderAll(data) {
    const { rows, result } = buildEmployeeRows(data);
    latestRows = rows;

    const setText = (id, v) => { const el = get(id); if (el) el.innerText = v; };
    setText("#kpi-p-count",       result.present_count);
    setText("#kpi-p-strict-count", result.present_only_count);
    setText("#kpi-a-count",       result.absent_count);
    setText("#kpi-h-count",       result.half_day_count);
    setText("#kpi-total-count",   result.total_emp_count);

    updateTabs();
    renderTable();
  }

  function updateTabs() {
    let present = 0, absent = 0, halfDay = 0;
    for (let i = 0; i < latestRows.length; i++) {
      const s = latestRows[i].status;
      if      (s === "Present" || s === "Half Day") present++;
      if (s === "Half Day") halfDay++;
      else if (s === "Absent") absent++;
    }
    const counts = { present, absent, half_day: halfDay, total: latestRows.length };

    const tabs = tabEls();
    for (let i = 0; i < tabs.length; i++) {
      const tab = tabs[i];
      const f = tab.getAttribute("data-filter");
      if      (f === "all")      tab.textContent = `All (${counts.total})`;
      else if (f === "present")  tab.textContent = `Present (${counts.present})`;
      else if (f === "absent")   tab.textContent = `Absent (${counts.absent})`;
      else if (f === "half_day") tab.textContent = `Half Day (${counts.half_day})`;
    }
  }

  // Filter matchers. Half Day rolls into Present (the Present tab and the
  // export's "Present" sheet both include Half Day rows). Absent and
  // Half Day remain strict.
  const FILTER_MATCHERS = {
    all:      () => true,
    present:  (s) => s === "Present" || s === "Half Day",
    absent:   (s) => s === "Absent",
    half_day: (s) => s === "Half Day",
  };

  function renderTable() {
    const body = tbody();
    if (!body) return;
    const activeFilter =
      root_element.querySelector(".status-tab.active")?.getAttribute("data-filter") || "all";
    const matcher = FILTER_MATCHERS[activeFilter] || FILTER_MATCHERS.all;

    const parts = [];
    let count = 0;
    for (let i = 0; i < latestRows.length; i++) {
      const r = latestRows[i];
      if (!matcher(r.status)) continue;
      count++;
      parts.push(
        "<tr><td class='cell-sr'>", count, "</td>",
        "<td><span class='cell-emp-name'>", escapeHtml(r.name),
        "</span><span class='cell-emp-id'>", escapeHtml(r.id), "</span></td>",
        "<td class='cell-ward'>",     escapeHtml(r.ward),         "</td>",
        "<td class='cell-org'>",      escapeHtml(r.organization), "</td>",
        "<td class='cell-desig'>",    escapeHtml(r.designation),  "</td>",
        "<td class='cell-date'>",     escapeHtml(r.attendance_date), "</td>",
        "<td>",
          (r.shift && r.shift !== "—")
            ? "<span class='cell-shift'>" + escapeHtml(r.shift) + "</span>"
            : "<span class='cell-shift empty'>—</span>",
        "</td>",
        "<td class='cell-time'>",  escapeHtml(r.in_time),  "</td>",
        "<td class='cell-time'>",  escapeHtml(r.out_time), "</td>",
        "<td class='cell-hours'>", escapeHtml(r.working_hours), "</td>",
        '<td class="cell-status"><span class="badge ', badgeClass(r.status), '">',
          r.status, "</span></td></tr>",
      );
    }

    if (count === 0) {
      const hasAnyRows = latestRows.length > 0;
      const emptyMsg = hasAnyRows
        ? `No records match the "${activeFilter.replace("_", " ")}" filter.`
        : "No records found. Try adjusting the filters or date.";
      body.innerHTML =
        `<tr><td colspan="11" style="text-align:center;padding:24px 12px;color:#6b7280;">` +
        `<div style="font-size:14px;font-weight:600;color:#374151;margin-bottom:4px;">${escapeHtml(emptyMsg)}</div>` +
        (hasAnyRows
          ? `<div style="font-size:12px;">Switch to "All" tab or clear the status filter.</div>`
          : `<div style="font-size:12px;">Use "Clear All" to reset filters and date.</div>`) +
        `</td></tr>`;
      return;
    }
    body.innerHTML = parts.join("");
  }

  // ============================================================
  // 9. NETWORK
  //   frappe RPC + a belt-and-suspenders client fallback for ward/org
  //   fields. The Python response should always populate these, but if
  //   it doesn't, we look them up via two extra get_list calls.
  // ============================================================

  function fetchExtraFields(empIds) {
    const empTuple = empIds || [];
    if (!empTuple.length) return Promise.resolve({ empWardMap: {}, empOrgMap: {} });

    return frappe
      .call({
        method: "frappe.client.get_list",
        args: {
          doctype: "Employee",
          fields: ["name", "company"],
          filters: { name: ["in", empTuple], status: "Active" },
          limit_page_length: 0,
        },
      })
      .then((res) => {
        const empCompany = {};
        (res.message || []).forEach((e) => { empCompany[e.name] = e.company || ""; });
        const uniqueCompanies = [...new Set(Object.values(empCompany).filter(Boolean))];
        if (!uniqueCompanies.length) return buildEmpMaps(empIds, empCompany, {});
        return frappe
          .call({
            method: "frappe.client.get_list",
            args: {
              doctype: "Company",
              fields: ["name", "custom_ward"],
              filters: { name: ["in", uniqueCompanies] },
              limit_page_length: 0,
            },
          })
          .then((r2) => {
            const companyWard = {};
            (r2.message || []).forEach((c) => { companyWard[c.name] = c.custom_ward || "—"; });
            return buildEmpMaps(empIds, empCompany, companyWard);
          });
      })
      .catch(() => ({ empWardMap: {}, empOrgMap: {} }));
  }

  function buildEmpMaps(empIds, empCompany, companyWard) {
    const empWardMap = {}, empOrgMap = {};
    empIds.forEach((eid) => {
      const comp = empCompany[eid] || "";
      empOrgMap[eid]  = comp || "—";
      empWardMap[eid] = companyWard[comp] || "—";
    });
    return { empWardMap, empOrgMap };
  }

  function init() {
    const selectedDate = get("#single-date")?.value || "";
    filtersDirty = false;
    showInlineLoader("Loading attendance data…");

    frappe.call({
      method: "get_data_k",
      args: {
        selected_date:       selectedDate,
        ward_filter:         getSelected("ms-ward").join(","),
        cp_type_filter:      getSelected("ms-cp-type").join(","),
        org_filter:          getSelected("ms-org").join(","),
        branch_filter:       getSelected("ms-org").join(","),
        dept_filter:         getSelected("ms-dept").join(","),
        designation_filter:  getSelected("ms-desig").join(","),
        shift_filter:        getSelected("ms-shift").join(","),
      },
      callback: (r) => {
        if (!r?.message) { hideInlineLoader(); return; }

        populateMultiSelect("ms-ward",    r.message.all_wards);
        populateMultiSelect("ms-cp-type", r.message.all_types);
        populateMultiSelect("ms-org",     r.message.all_branches || r.message.all_orgs || []);
        populateMultiSelect("ms-dept",    r.message.all_depts);
        populateMultiSelect("ms-desig",   r.message.all_designations);
        populateMultiSelect("ms-shift",   r.message.all_shifts);

        // Master employee list. Priority:
        //   1. all_employee — server returns the FULL list of active/contract
        //      employees matching the filter. This is the only source that
        //      includes ABSENT employees with no checkin row.
        //   2. emp_dept_map keys — fallback if all_employee is empty.
        //   3. union of employees in all_checkin — last resort, won't have
        //      absentees but at least renders something.
        const rawAllEmployee = r.message.all_employee;
        let empIds = [];
        if (Array.isArray(rawAllEmployee))                              empIds = rawAllEmployee;
        else if (rawAllEmployee && typeof rawAllEmployee === "object")  empIds = Object.keys(rawAllEmployee);

        const empDeptMapResp = r.message.emp_dept_map || {};
        if (!empIds.length && Object.keys(empDeptMapResp).length)       empIds = Object.keys(empDeptMapResp);

        if (!empIds.length) {
          const seen = new Set();
          (r.message.all_checkin || []).forEach((c) => { if (c.employee) seen.add(c.employee); });
          empIds = Array.from(seen);
        }

        // Seed absent employees with the selected date so the table shows
        // the date for everyone (Attendance list view shows the date too).
        const checkinDerived = {};
        for (let i = 0; i < empIds.length; i++) {
          checkinDerived[empIds[i]] = {
            attendance_date: selectedDate, first_in: null, last_out: null, working_hours: null,
          };
        }
        (r.message.all_checkin || []).forEach((c) => {
          const eid = c.employee;
          if (!eid) return;
          const s = checkinDerived[eid] || (checkinDerived[eid] = {
            attendance_date: selectedDate, first_in: null, last_out: null, working_hours: null,
          });
          const lt = (c.log_type || "").toUpperCase();
          const t = c.time;
          if (!t) return;
          if      (lt === "IN")  { if (!s.first_in || String(t) < String(s.first_in)) s.first_in = t; }
          else if (lt === "OUT") { if (!s.last_out || String(t) > String(s.last_out)) s.last_out = t; }
        });
        for (const eid in checkinDerived) {
          const s = checkinDerived[eid];
          if (s.first_in && s.last_out) {
            const ms = new Date(s.last_out) - new Date(s.first_in);
            if (!isNaN(ms) && ms > 0) s.working_hours = Math.round((ms / 3600000) * 100) / 100;
          }
        }

        const augmented = Object.assign({}, r.message, {
          emp_ward_map: r.message.emp_ward_map || {},
          emp_org_map:  r.message.emp_org_map  || {},
        });

        if (!augmented.attendance_by_emp || !Object.keys(augmented.attendance_by_emp).length) {
          augmented.attendance_by_emp = checkinDerived;
        } else {
          // Per-employee fallback: the server's `attendance_by_emp` is
          // built from tabAttendance rows, so absentees end up with `{}`
          // and `attendance_date` is undefined. Seed it from checkinDerived
          // so the table shows the date for everyone on first load.
          for (const eid in checkinDerived) {
            const serverRow = augmented.attendance_by_emp[eid];
            if (!serverRow || !serverRow.attendance_date) {
              if (!augmented.attendance_by_emp[eid]) augmented.attendance_by_emp[eid] = {};
              augmented.attendance_by_emp[eid].attendance_date = checkinDerived[eid].attendance_date;
            }
          }
        }

        const needClientWardOrg =
          !Object.keys(augmented.emp_ward_map).length ||
          !Object.keys(augmented.emp_org_map).length;

        const finalize = (extra) => {
          if (extra) {
            if (!Object.keys(augmented.emp_ward_map).length && extra.empWardMap) augmented.emp_ward_map = extra.empWardMap;
            if (!Object.keys(augmented.emp_org_map).length  && extra.empOrgMap)  augmented.emp_org_map  = extra.empOrgMap;
          }
          renderAll(augmented);
          hideInlineLoader();
        };

        if (needClientWardOrg) fetchExtraFields(empIds).then(finalize);
        else                    finalize(null);
      },
    });
  }

  // ============================================================
  // 10. EXPORT
  // ============================================================

  function exportToExcel() {
    if (!latestRows.length) {
      frappe.msgprint("No data to export.");
      return;
    }
    const btn = get("#btn-export");
    setBtnLoading(btn, true);
    setTimeout(() => setBtnLoading(btn, false), 0);

    function doExport() {
      const formatRows = (rows) => rows.map((r, idx) => ({
        "Sr No":          idx + 1,
        "Employee Name":  r.name,
        Ward:             r.ward,
        Organization:     r.organization,
        Designation:      r.designation,
        "Attendance Date": r.attendance_date,
        Shift:            r.shift,
        "In Time":        r.in_time,
        "Out Time":       r.out_time,
        "Working Hours":  r.working_hours,
        Status:           r.status,
      }));

      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(formatRows(latestRows)),                       "All Employees");
      XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(formatRows(latestRows.filter((r) => r.status === "Present" || r.status === "Half Day"))), "Present");
      XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(formatRows(latestRows.filter((r) => r.status === "Absent"))),   "Absent");
      XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(formatRows(latestRows.filter((r) => r.status === "Half Day"))), "Half Day");

      XLSX.writeFile(wb, `attendance_${get("#single-date")?.value || "export"}.xlsx`);
    }

    if (typeof XLSX !== "undefined") {
      doExport();
    } else {
      const script = document.createElement("script");
      script.src = "https://cdn.jsdelivr.net/npm/xlsx/dist/xlsx.full.min.js";
      script.onload = doExport;
      script.onerror = () => frappe.msgprint("Failed to load export library.");
      document.head.appendChild(script);
    }
  }

  // ============================================================
  // 11. WIRING — top-level event hooks
  // ============================================================

  function bindCloseOnOutsideClick() {
    document.addEventListener("click", closeAllDropdowns);
  }

  function bindDatePicker() {
    get("#single-date")?.addEventListener("change", () => {
      renderActiveFilters();
      markDirty();
      init();
    });
  }

  function bindStatusTabs() {
    root_element.querySelectorAll(".status-tab").forEach((tab) => {
      tab.addEventListener("click", () => {
        root_element.querySelectorAll(".status-tab").forEach((t) => t.classList.remove("active"));
        tab.classList.add("active");
        updateTabs();
        renderTable();
      });
    });
  }

  function bindClearAll() {
    get("#btn-reset")?.addEventListener("click", () => {
      MS_ORDER.forEach((id) => { msState[id].selected = []; updateTriggerLabel(id); });
      tabEls().forEach((t) => t.classList.remove("active"));
      root_element.querySelector('.status-tab[data-filter="all"]')?.classList.add("active");
      resetDateInputs();
      markDirty();
      init();
    });
  }

  function bindExport() {
    get("#btn-export")?.addEventListener("click", exportToExcel);
  }

  function bootstrap() {
    bindCloseOnOutsideClick();
    bindDatePicker();
    MS_ORDER.forEach(buildMultiSelect);
    resetDateInputs();
    init();
    bindStatusTabs();
    bindClearAll();
    bindExport();
  }

  bootstrap();
})();

style:
/* --- 1. DASHBOARD & TITLES --- */
.dash-temp-container {
    font-family: Inter, 'Segoe UI', system-ui, -apple-system, sans-serif;
    background: #fdfdfd;
    padding: 1rem;
}
/* --- LOADER (inline, non-blocking) --- */
.inline-loader {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 6px 10px;
    margin: 6px 0;
    background: #f5f7fa;
    border: 1px solid #e0e6ed;
    border-radius: 6px;
    color: #4a5568;
    font-size: 12px;
    width: fit-content;
}

.inline-loader-spinner,
.btn-spinner {
    display: inline-block;
    width: 12px;
    height: 12px;
    border: 2px solid #cbd5e0;
    border-top-color: #0F6E56;
    border-radius: 50%;
    animation: spin 0.7s linear infinite;
}

.inline-loader-spinner {
    width: 14px;
    height: 14px;
}

@keyframes spin {
    to { transform: rotate(360deg); }
}

.section-header-vertical {
    border-bottom: 2px solid #0F6E56;
    margin-bottom: 12px;
}

.main-title h2 {
    color: #0F6E56;
    font-size: 18px;
    margin-bottom: 8px;
    font-weight: 700;
}


.main-title {
    color: #0F6E56;
    font-size: 18px;
    margin-bottom: 8px;
    font-weight: 700;
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
}

.main-title h2 {
    margin: 0;
}

.title-actions {
    display: flex;
    gap: 10px;
}



/* --- 2. FILTER BAR --- */
.header-actions {
    display: flex;
    flex-wrap: nowrap;
    align-items: center;
    gap: 4px;
    margin-bottom: 15px;
    overflow: visible;
    width: 100%;
}

.filter-bar {
    display: grid;
    grid-template-columns: repeat(6, minmax(0, 1fr)) 1.4fr;
    gap: 10px;
    align-items: end;
    margin: 10px 0 14px;
    padding: 12px;
    background: linear-gradient(180deg, #f8fbf9 0%, #f3f7f5 100%);
    border: 1px solid #e3ece8;
    border-radius: 10px;
    box-shadow: 0 1px 2px rgba(15,110,86,0.04);
}

/* Responsive: collapse the grid into fewer columns on narrow screens.
   Note: `.filter-field-wide` (Date) collapses together with the rest. */
@media (max-width: 1100px) {
    .filter-bar { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}
@media (max-width: 720px) {
    .filter-bar { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

/* Date column gets a slightly wider track than the 1fr filter fields
   so the locale-formatted date ("08/07/2026") + calendar chevron fit
   without crowding the other columns. */
.filter-field-wide {
    grid-column: span 1;
}

.filter-field {
    display: flex;
    flex-direction: column;
    justify-content: flex-end;     /* align label + control to the same baseline */
    gap: 4px;
    min-width: 0;
    height: 100%;
}

.filter-label {
    font-size: 10px;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #0F6E56;
    padding-left: 2px;
}

.date-input {
    flex: 1;
    min-width: 0;
    width: 100%;
    height: 30px;
    min-height: 30px;
    padding: 0 10px;
    border-radius: 6px;
    border: 1px solid #d4dce0;
    font-size: 13px;
    background: #fff;
    font-weight: 600;
    color: #2d3748;
    cursor: pointer;
    transition: border-color 0.15s, box-shadow 0.15s;
    box-sizing: border-box;
    line-height: 1;
}
.date-input:hover { border-color: #0F6E56; }
.date-input:focus { outline: none; border-color: #0F6E56; box-shadow: 0 0 0 3px rgba(15,110,86,0.15); }

.date-range-box {
    display: flex;
    align-items: center;
    gap: 2px;
    background: #fff;
    padding: 0;
    border-radius: 6px;
    border: 1px solid #d4dce0;
    flex-shrink: 1;
    width: 100%;
    height: 32px;
    min-height: 32px;
    min-width: 0;
    box-sizing: border-box;
    overflow: hidden;
    transition: border-color 0.15s, box-shadow 0.15s;
}
.date-range-box .date-input {
    width: 100%;
    min-width: 0;
    border: none;
    background: transparent;
    box-shadow: none;
}
.date-range-box .date-input:focus { box-shadow: none; }
.date-range-box:focus-within { border-color: #0F6E56; box-shadow: 0 0 0 3px rgba(15,110,86,0.15); }

.range-sep { font-weight: 800; color: #0F6E56; font-size: 11px; }

/* Buttons — primary vs ghost. Heights are locked to match the
   .ms-trigger / .date-input controls below so the title row and the
   filter bar read as one continuous toolbar rather than two separate strips. */
.btn {
    display: inline-flex !important;          /* override Frappe's a.btn { display: ... } */
    align-items: center;
    justify-content: center;
    gap: 6px;
    height: 32px;
    min-height: 32px;                         /* belt-and-suspenders against Frappe's font-size rule */
    max-height: 32px;
    padding: 0 14px;
    border-radius: 6px;
    font-weight: 700;
    font-size: 12px;
    line-height: 1;
    flex-shrink: 0;
    cursor: pointer;
    transition: all 0.15s ease;
    font-family: inherit;
    box-sizing: border-box;
    white-space: nowrap;
    vertical-align: middle;
