    border-width: 1px;
    border-style: solid;
}
.btn-primary {
    /* Gradient + 2-stop shadow make the primary read as a deliberate, weighty
       action rather than a flat button. Used for "Export Excel". */
    background: linear-gradient(180deg, #138067 0%, #0F6E56 100%);
    border-color: #0A5440;
    color: #ffffff;
    box-shadow:
        inset 0 1px 0 rgba(255,255,255,0.18),
        0 1px 2px rgba(10,84,64,0.35),
