    box-shadow:
        inset 0 1px 0 rgba(255,255,255,0.22),
        0 3px 8px rgba(10,84,64,0.4),
        0 0 0 1px rgba(10,84,64,0.12);
}
.btn-primary:active {
    background: linear-gradient(180deg, #0F6E56 0%, #0A5440 100%);
    box-shadow: inset 0 1px 2px rgba(0,0,0,0.12);
}
.btn-primary:focus-visible { outline: none; box-shadow: 0 0 0 3px rgba(15,110,86,0.4); }

.btn-ghost {
    background: #ffffff;
