    color: #495057;
    box-shadow: 0 1px 2px rgba(0,0,0,0.04);
}
.btn-ghost:hover { border-color: #0F6E56; color: #0F6E56; background: #f0faf6; box-shadow: 0 1px 3px rgba(15,110,86,0.15); }
.btn-ghost:focus-visible { outline: none; border-color: #0F6E56; box-shadow: 0 0 0 3px rgba(15,110,86,0.15); }

/* Legacy alias — older templates referenced .reset-btn directly */
.reset-btn {
    display: inline-flex !important;
    align-items: center;
    justify-content: center;
    gap: 6px;
    height: 32px;
    min-height: 32px;
    max-height: 32px;
    padding: 0 14px;
    border-radius: 6px;
    font-weight: 700;
    font-size: 12px;
    line-height: 1;
    flex-shrink: 0;
    cursor: pointer;
    transition: all 0.15s ease;
