    font-size: 13px;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.12s;
    color: #333;
}

.ms-option:hover { background: #f0faf6; }

.ms-option input[type="checkbox"] {
    accent-color: #0F6E56;
    width: 14px;
    height: 14px;
    min-width: 14px;
    min-height: 14px;
    cursor: pointer;
    flex-shrink: 0;
    margin: 0 !important;                     /* kill Frappe's default input margin */
    padding: 0 !important;                    /* kill Frappe's default input padding */
    vertical-align: middle;
}

.ms-option label {
    cursor: pointer;
    flex: 1;
    min-width: 0;                              /* let label shrink so ellipsis kicks in instead of forcing checkbox to move */
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    line-height: 1.3;
    margin: 0;
    padding: 0;
}

.ms-no-results {
    padding: 12px;
    font-size: 12px;
    color: #999;
    text-align: center;
    font-style: italic;
}

.ms-count-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: #0F6E56;
    color: #fff;
    font-size: 10px;
    font-weight: 800;
    min-width: 18px;
    height: 18px;
    padding: 0 6px;
    border-radius: 5px;
    margin-right: 6px;
    vertical-align: middle;
    flex-shrink: 0;
    box-sizing: border-box;
    line-height: 1;
}

/* --- 4. EXCEPTION TABLES --- */
.exception-tables-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
    margin-bottom: 20px;
    align-items: flex-start;
}

/* --- 5. CHART ROWS --- */
.charts-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
    margin-bottom: 20px;
}

.charts-row-1col {
    display: flex;
    display: grid;
    grid-template-columns: 1fr;
    gap: 20px;
    margin-bottom: 20px;
}

.card {
    background: #fff;
    padding: 12px;
    border-radius: 10px;
    border: 1px solid #eee;
    width: 100%;
}

/* Edge-to-edge variant for cards that wrap the employee table —
   removes internal padding so the table sits flush against the card
   border and the scrollbar lives at the card edge instead of
   floating inside a white gutter. */
.card-flush { padding: 0; overflow: hidden; }
.card-flush .table-scroll { border-radius: 10px; }

.card h3 {
    font-size: 12px;
    text-transform: uppercase;
    color: #0F6E56;
    margin-bottom: 10px;
    font-weight: 800;
    border-left: 3px solid #0F6E56;
    padding-left: 8px;
}

/* --- 6. TABLE --- */
table { width: 100%; border-collapse: collapse; border-spacing: 0; table-layout: auto; }

/* Column sizing — keep the table from overflowing horizontally so the
   Status column doesn't get clipped. The first column (Sr No) gets
   the smallest fixed track; the Employee Name column (now 2nd) gets
   the widest track so the longest names stay on one line. */
table th:nth-child(1), table td:nth-child(1) { width: 50px; min-width: 50px; }
table th:nth-child(2), table td:nth-child(2) { width: 180px; min-width: 160px; }
table th:nth-child(3), table td:nth-child(3) { width: 60px; min-width: 60px; }
table th:nth-child(4), table td:nth-child(4) { width: 130px; min-width: 110px; }
table th:nth-child(5), table td:nth-child(5) { width: 110px; min-width: 100px; }
table th:nth-child(6), table td:nth-child(6) { width: 95px; min-width: 90px; }
table th:nth-child(7), table td:nth-child(7) { width: 110px; min-width: 100px; }
table th:nth-child(8), table td:nth-child(8) { width: 70px; min-width: 65px; }
table th:nth-child(9), table td:nth-child(9) { width: 75px; min-width: 70px; }
table th:nth-child(10), table td:nth-child(10) { width: 95px; min-width: 90px; }
table th:nth-child(11), table td:nth-child(11) { width: 90px; min-width: 85px; }

th {
    text-align: left;
    color: #0F6E56;
    font-size: 11px;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.4px;
    padding: 12px 10px;
    background: #f8fbf9;
    white-space: nowrap;
    border-bottom: 2px solid #0F6E56;
}

/* Make the entire header row stick to the top of the scroll container
   so it stays visible while the body scrolls. */
.table-scroll thead { position: sticky; top: 0; z-index: 5; }

td {
    font-size: 13px;
    padding: 10px 10px;
    border-bottom: 1px solid #f1f3f5;
    vertical-align: middle;
    font-weight: 500;
    color: #2d3748;
    line-height: 1.4;
}

/* Zebra striping — makes long lists easier to scan */
tbody tr:nth-child(even) td { background: #fafcfb; }

.table-scroll {
    max-height: 600px;
    overflow-y: auto;
    overflow-x: auto;
    background: #fff;
}
/* Subtle, thin scrollbar that doesn't fight the rest of the design.
   The track is transparent and the thumb is a soft slate, narrow
   enough to feel like an indicator rather than a chrome element. */
.table-scroll::-webkit-scrollbar { width: 6px; height: 6px; }
.table-scroll::-webkit-scrollbar-track { background: transparent; }
.table-scroll::-webkit-scrollbar-thumb {
    background: #d0d6dd;
    border-radius: 999px;
}
.table-scroll::-webkit-scrollbar-thumb:hover { background: #0F6E56; }
.table-scroll { scrollbar-width: thin; scrollbar-color: #d0d6dd transparent; }

/* --- 7. BADGES --- */
.badge {
    display: inline-block;
    padding: 4px 10px;
    border-radius: 12px;
    font-size: 11px;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.3px;
    box-shadow: inset 0 0 0 1px rgba(0,0,0,0.04);
}
.badge-green { background: #E1F5EE; color: #0F6E56; }
.badge-red   { background: #FDEAEC; color: #9B1C2A; }
.badge-amber { background: #FFF3CD; color: #8B5E00; }
.badge-blue  { background: #E6F1FB; color: #185FA5; }
.badge-gray  { background: #f0f0f0; color: #666; }

/* Cell variants — prevent narrow columns from wrapping times/dates. */
.cell-time, .cell-date { white-space: nowrap; font-variant-numeric: tabular-nums; color: #2d3748; }
.cell-shift {
    display: inline-block;
    padding: 2px 6px;
    border-radius: 4px;
    background: transparent;
    color: #2d3748;
    font-size: 12px;
    font-weight: 600;
    border: 1px solid #e3ece8;
    white-space: nowrap;
}
.cell-shift.empty { background: transparent; color: #999; border-color: #ececec; }
.cell-hours { white-space: nowrap; font-variant-numeric: tabular-nums; color: #2d3748; font-weight: 600; }

.cell-emp-name {
    font-weight: 700;
    color: #2d3748;
    display: block;
    max-width: 100%;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.cell-emp-id { display: block; font-size: 10px; color: #888; font-weight: 500; margin-top: 2px; }
.cell-ward, .cell-org, .cell-desig, .cell-dept {
    color: #2d3748;
    max-width: 100%;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.cell-status { text-align: center; }

/* --- 8. BUTTONS --- */
.view-more-btn {
    display: inline-block;
    margin-top: 15px;
    background: #f1f3f5;
    border: 1px solid #dee2e6;
    color: #0F6E56;
    padding: 6px 24px;
    border-radius: 20px;
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    cursor: pointer;
    transition: all 0.2s ease;
}

.view-more-btn:hover { background: #0F6E56; color: #ffffff; border-color: #0F6E56; }

.mini-toggle {
    display: block;
    margin-left: auto;
    margin-top: 8px;
    background: none;
    border: none;
    color: #0F6E56;
    font-size: 10px;
    font-weight: 700;
    cursor: pointer;
}

.btn-container { text-align: center; width: 100%; }

/* --- 9. KPI BOXES --- */
.kpi-grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-bottom: 15px; }
.kpi { background: #fff; padding: 12px; border-radius: 10px; border: 1px solid #eee; text-align: center; }
.kpi-teal  { border-top: 4px solid #0F6E56; }
.kpi-red   { border-top: 4px solid #e0324d; }
.kpi-amber { border-top: 4px solid #D48000; }
.kpi-label { font-size: 14px; font-weight: 600; color: #666; }
.kpi-value { font-size: 28px; font-weight: 800; color: #212529; }

/* --- 10. LIVE DETAILS SCROLL --- */
#live-details-scroll {
    max-height: none;
    overflow-y: visible;
}

#live-details-scroll.expanded {
    max-height: 400px;
    overflow-y: auto;
    border: 1px solid #eee;
    border-radius: 8px;
    padding-right: 5px;
}
/* Update this selector */
.kpi-grid-4 { 
    display: grid; 
    grid-template-columns: repeat(4, 1fr); 
    gap: 10px; 
    margin-bottom: 15px; 
}

/* Add this for the Total box color */
.kpi-blue { border-top: 4px solid #378ADD; }

#live-details-scroll::-webkit-scrollbar { width: 6px; }
#live-details-scroll::-webkit-scrollbar-track { background: #f1f1f1; }
#live-details-scroll::-webkit-scrollbar-thumb { background: #0F6E56; border-radius: 10px; }


/* --- 11. CHECK-IN SOURCE SECTION --- */
.checkin-source-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
    margin-bottom: 14px;
}

.source-block {
    background: #fff;
    border-radius: 10px;
    border: 1px solid #eee;
    padding: 12px;
}

.source-bio { border-top: 4px solid #378ADD; }
.source-web { border-top: 4px solid #0F6E56; }

.source-block-title {
    font-size: 13px;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.4px;
    margin-bottom: 10px;
    padding-left: 8px;
    border-left: 3px solid currentColor;
}

.badge-bio { background: #E6F1FB; color: #185FA5; }
.badge-web { background: #E1F5EE; color: #0F6E56; }


.full-width-card {
    width: 100%;
    box-sizing: border-box;
}

.charts-row-1col {
    width: 100%;
    display: flex;
}

.charts-row-1col .card {
    flex: 1;
}

/* --- 12. STATUS FILTER TABS (employee table) --- */
.status-tabs {
    display: flex;
    gap: 6px;
    margin-bottom: 12px;
    flex-wrap: wrap;
    align-items: center;
}

.status-tab {
    background: #f1f3f5;
    border: 1px solid #ced4da;
    color: #495057;
    padding: 6px 14px;
    border-radius: 4px;
    font-weight: 700;
    font-size: 12px;
    cursor: pointer;
    transition: all 0.2s ease;
}

.status-tab:hover { border-color: #0F6E56; color: #0F6E56; }

.status-tab.active {
    background: #0F6E56;
    color: #ffffff;
    border-color: #0F6E56;
}
